// The gateway owns raw history. This node runs again after each compression pass.
const incoming = $input.first().json;
const initial = incoming.body !== undefined;
if (initial && !/^[A-Za-z0-9_-]{40,128}$/.test(incoming.headers?.['x-enzymind-turn'] || '')) throw new Error('A gateway-issued execution capability is required.');
const state = initial ? {...incoming.body, compression_count:0,summary_attempt:0,retry_summary:false,compression_deferred:false} : {...incoming};
if (state.billing_mode === 'byok' && !/^[a-f0-9]{64}$/.test(state.model_relay_token || '')) throw new Error('Invalid workspace request: missing temporary model capability.');
if (state.billing_mode && !['free','byok'].includes(state.billing_mode)) throw new Error('Invalid workspace request: billing mode.');
if (typeof state.message !== 'string' || !Array.isArray(state.history) || state.history.length % 2 || typeof state.summary !== 'string' || !Number.isInteger(state.summarized_count) || state.summarized_count < 0 || state.summarized_count % 2) throw new Error('Invalid workspace request.');
if (state.history.some((h,i)=>h.role !== (i%2?'assistant':'user') || typeof h.content !== 'string')) throw new Error('History must contain complete user/assistant pairs.');
const tokens = value => Math.ceil([...String(value)].reduce((sum,c)=>sum+(c.codePointAt(0)<128?1:6),0)/3);
// Replaced by the builder using the actual system prompt and tool descriptions.
const reserve = 8055;
const contextLimit = 100000;
const context = {summary:state.summary,history:state.history,message:state.message,evidence:state.evidence || [],result_index:state.result_index || []};
const estimate = reserve + tokens(JSON.stringify(context));
let compressCount = 0;
if (estimate > contextLimit && state.history.length && !state.compression_deferred && state.compression_count < 100) {
  // First preserve three recent exchanges; if they alone are too large, reduce
  // the window by whole exchanges. Never slice a question, answer or evidence.
  const available = Math.max(2,state.history.length - 6);
  for (let n=2;n<=available;n+=2) {
    const batchSize = tokens(JSON.stringify({summary:state.summary,history:state.history.slice(0,n)}));
    if (batchSize > 10000) break; // Summary-call batch size, not the Agent context threshold.
    compressCount = n;
  }
}
// This estimate is a compression target, not the selected model's context limit.
// Continue with intact input when there is nothing suitable left to summarize.
const contextWarning = !compressCount && estimate > contextLimit;
return [{json:{...state,context_tokens:estimate,context_warning:contextWarning,needs_compression:compressCount>0,compress_count:compressCount,retained_messages:state.history.length-compressCount}}];

// Anchor each attempt, not each context pass: a summary retry does not run
// Evaluate context again. Explicit run indices also avoid reading pass zero.
const state = $('Prepare memory summary').first(0, $runIndex).json;
if (!Array.isArray(state.history) || !Number.isInteger(state.compress_count) ||
    state.compress_count < 2 || state.compress_count % 2 || state.compress_count > state.history.length ||
    !Number.isInteger(state.context_tokens) || state.context_tokens < 0 ||
    !Number.isInteger(state.summary_attempt) || ![0, 1].includes(state.summary_attempt)) {
  throw new Error('Invalid workspace request: memory compression state. The original conversation is preserved.');
}
const text = $input.first().json.text;
const summary = typeof text === 'string' ? text.trim() : '';
const tokens = value => Math.ceil([...value].reduce((n,c)=>n+(c.codePointAt(0)<128?1:6),0)/3);
const size = tokens(summary);
const previousSize = tokens(JSON.stringify({summary:state.summary,history:state.history.slice(0,state.compress_count)}));
const issue = !summary ? 'empty' : size > 1600 ? 'too_long' : size >= previousSize ? 'not_shorter' : '';
if (!issue) {
  return [{json:{...state,summary,summarized_count:state.summarized_count+state.compress_count,
    history:state.history.slice(state.compress_count),compression_count:state.compression_count+1,
    summary_attempt:0,retry_summary:false,summary_issue:'',summary_tokens:size,compression_deferred:false}}];
}
// Compression is advisory. Keep every original
// message and the exact persisted summary; never commit an invalid replacement.
if (state.context_tokens <= 100000 || state.summary_attempt === 1) {
  return [{json:{...state,retry_summary:false,summary_issue:issue,summary_tokens:size,compression_deferred:true}}];
}
// One corrective generation from the original material, not from a lossy draft.
if (state.summary_attempt === 0) {
  return [{json:{...state,summary_attempt:1,retry_summary:true,summary_issue:issue,summary_tokens:size}}];
}

const state = $('Research context').first().json;
const output = $input.first().json.output;
if (typeof output !== 'string' || !output.trim()) throw new Error('The research agent did not return an answer.');
return [{json:{output,summary:state.summary,summarized_count:state.summarized_count,memory_revision:state.memory_revision,compression_count:state.compression_count,context_tokens:state.context_tokens,billing_mode:state.billing_mode || 'free'}}];

parameters.toolDescription:
Predict active sites and binding residues using EasIFA.
Input must be a JSON object using ONE of the following formats:
1. By ID: {"uniprot_id": "P12345"}
2. By Sequence: {"aa_sequence": "MKF..."}
3. By Sequence + Reaction: {"aa_sequence": "MKF...", "rxn_smiles": "CC(=O)O>>CC(=O)OC"}
The tool returns a formatted Markdown table listing residue indices, names, active types, and confidence scores.

